class PayrollService {
    fun calculatePay(employee: Employee): Money = calculateByFinanceRules(employee)
    fun exportAuditCsv(employees: List<Employee>): String = encodeAuditSchema(employees)
}

class Checkout(private val validator: Validator, private val orders: Orders, private val events: Events) {
    fun place(order: Order) {
        validator.validate(order)
        orders.save(order)
        events.recordPlaced(order)
    }
}

public interface DocumentService {
    Document load(String id);
    void save(Document document);
    String render(Document document);
}

Object convert(Object source, Class<?> targetType) {
    if (targetType == ExternalId.class) return new ExternalId(source.toString());
    return existingGenericConversion(source, targetType);
}

sealed interface Outcome {
    data class Success(val value: String) : Outcome
    data class Failure(val cause: Throwable) : Outcome
}
fun label(outcome: Outcome): String = when (outcome) {
    is Outcome.Success -> outcome.value
    is Outcome.Failure -> "failed"
}

class SingleCloseSource(delegate: Source) : ForwardingSource(delegate) {
    private var closed = false
    override fun close() {
        check(!closed)
        closed = true
        super.close()
    }
}

interface Cache {
    fun read(key: String): String?
    fun write(key: String, value: String)
}
class ReadOnlyCache : Cache {
    override fun read(key: String): String? = load(key)
    override fun write(key: String, value: String) = throw UnsupportedOperationException()
}
class Renderer(private val cache: Cache)

class Producer(private val output: SendChannel<Event>) {
    suspend fun publish(event: Event) { output.send(event) }
}

class CodecRunner<T>(private val serializer: KSerializer<T>) {
    fun encode(encoder: Encoder, value: T) = serializer.serialize(encoder, value)
    fun decode(decoder: Decoder): T = serializer.deserialize(decoder)
    val descriptor get() = serializer.descriptor
}

import storage.JdbcPriceRepository
import java.sql.Connection
class PricingPolicy(private val repository: JdbcPriceRepository) {
    fun price(connection: Connection, id: ProductId): Money = repository.readPrice(connection, id)
}

final class TaxCalculator {
    BigDecimal tax(BigDecimal subtotal, BigDecimal rate) { return subtotal.multiply(rate); }
}

@Service
class OrderService(private val orders: Orders, private val outbox: Outbox) {
    fun place(order: Order) { saveBoth(order) }
    @Transactional
    fun saveBoth(order: Order) { orders.save(order); outbox.save(order) }
}

interface Sender { suspend fun send(message: Message): Result }
class AsyncSender(private val applicationScope: CoroutineScope, private val client: Client) : Sender {
    override suspend fun send(message: Message): Result {
        applicationScope.launch { client.send(message) }
        return Result.Queued
    }
}

class BonusPolicy(private val store: JdbcSalesStore) {
    fun bonus(employeeId: String): Int {
        val sales = store.totalSales(employeeId)
        return if (sales >= 100) 10 else 0
    }
}

class JdbcSalesStore(private val readTotal: (String) -> Int) {
    fun totalSales(employeeId: String): Int = readTotal(employeeId)
}
